FuncDef.Code:
void opRevolutionTwistedSin(inout vec3 p, in float radius, in float cycles, in float amplitude, in float innerRot, in float angleOffset)
{
    float a = atan(p.z, p.x);
    g_shapeLoop = a;

    p.xz *= mat2(cos(a), sin(a), -sin(a), cos(a));
    p.x -= radius;

    a += PI;

    float a2 = a * cycles;

    a2 = innerRot + amplitude * 0.5 * sin(a2 + angleOffset * PI);

    p.xy *= mat2(cos(a2), sin(a2), -sin(a2), cos(a2));

    p.xz = vec2(length(p.xz), p.y);
}
